data.script:
const lines = draft.content.replace(/\r\n?/g, '\n').split('\n');
const items = []; let project = null, task = null, destination = '', error = '';
function invalid(message) { if (!error) error = message; }
function target() { return task || project; }
for (const line of lines) {
  if (!line.trim() || line.startsWith('//')) continue;
  if (line.startsWith('## ')) {
    const title = line.slice(3).trim();
    if (!project || !title) { invalid('A heading needs a project and a title.'); break; }
    project.attributes.items.push({type:'heading', attributes:{title}}); task = null;
  } else if (line.startsWith('# ')) {
    const title = line.slice(2).trim();
    if (!title) { invalid('A project needs a title.'); break; }
    project = {type:'project',attributes:{title,items:[]}};
    if (destination) project.attributes.area = destination;
    items.push(project); task = null;
  } else if (line.startsWith('- ')) {
    const title = line.slice(2).trim();
    if (!task || !title) { invalid('A checklist item needs a task and a title.'); break; }
    if (!task.attributes['checklist-items']) task.attributes['checklist-items'] = [];
    if (task.attributes['checklist-items'].length >= 100) { invalid('A task can have at most 100 checklist items.'); break; }
    task.attributes['checklist-items'].push({type:'checklist-item',attributes:{title}});
  } else if (line.startsWith('>')) {
    const current = target(); if (!current) { invalid('A note needs a task or project.'); break; }
    const note = line.slice(1).replace(/^ /,'');
    current.attributes.notes = current.attributes.notes ? current.attributes.notes + '\n' + note : note;
    if (current.attributes.notes.length > 10000) { invalid('Notes exceed the Things limit.'); break; }
  } else if (line.startsWith('@')) {
    destination = line.slice(1).trim();
    if (!destination) { invalid('A destination needs a name.'); break; }
    project = null; task = null;
  } else if (line.startsWith('#') || line.startsWith(':') || line.startsWith('!')) {
    const current = target(); const value = line.slice(1).trim();
    if (!current || !value) { invalid('A tag or date needs a task or project and a value.'); break; }
    if (line[0] === '#') { if (!current.attributes.tags) current.attributes.tags = []; current.attributes.tags.push(value); }
    else current.attributes[line[0] === ':' ? 'when' : 'deadline'] = value;
  } else {
    const title = line.trim(); if (title.length > 4000) { invalid('A title exceeds the Things limit.'); break; }
    task = {type:'to-do',attributes:{title}};
    if (project) project.attributes.items.push(task);
    else { if (destination) task.attributes.list = destination; items.push(task); }
  }
}
if (error) context.fail(error);
else if (!items.length) context.fail('Add at least one task or project.');
else {
  const callback = CallbackURL.create();
  callback.baseURL = 'things:///json?data=' + encodeURIComponent(JSON.stringify(items));
  if (!callback.open()) {
    if (callback.status === 'cancelled') context.cancel();
    else context.fail('Things did not confirm the import.');
  }
}
